{"command":"python3 << 'EOF'
from rdflib.plugins.sparql import prepareQuery
prefix = """PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wds: <http://www.wikidata.org/prop/statement/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX geo: <http://www.opengeospatial.org/ont/geo/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
"""
tests = {
 "a": prefix + "SELECT ?s WHERE { ?s wds:P625 ?o }",
 "b": prefix + "SELECT ?s WHERE { ?s wdt:P31/wdt:P279* ?t . ?s wds:P625 ?o }",
 "c": prefix + "SELECT ?s WHERE { ?item wdt:P31/wdt:P279* ?type . ?item wdt:P276* wd:Q11959 . ?item wds:P625 ?o }",
}
for k,q in tests.items():
    try:
        prepareQuery(q); print(k,"ok")
    except Exception as e:
        print(k,"FAIL:",e)
EOF"}

